            torch_dtype=torch.bfloat16,
        ).to("cuda")

    @modal.method()
    def generate_diagram(self, prompt: str) -> bytes:
        import io

        image = self.pipe(
            prompt,
            num_inference_steps=4,
            guidance_scale=0.0,
            height=512,
            width=512,
        ).images[0]
        buf = io.BytesIO()
        image.save(buf, format="PNG")
        return buf.getvalue()

